INSERT INTO `abouts` VALUES (1,'30 Tahun Mengabdi, Kualitas Terbukti','30-tahun-mengabdi-kualitas-terbukti','Selamat datang di Universitas BTH.','<p>Universitas Bakti Tunas Husada (Universitas BTH) adalah institusi pendidikan tinggi yang berdedikasi untuk menciptakan sumber daya manusia yang unggul, inovatif, dan profesional. Berdiri di atas fondasi yang kokoh sejak tahun 1993, kami telah bertransformasi menjadi sebuah universitas komprehensif yang secara unik mengintegrasikan tiga pilar keilmuan strategis: Kesehatan, Teknologi, dan Bisnis.<br><br>Didukung oleh tenaga pendidik ahli, fasilitas modern, dan kurikulum yang relevan dengan kebutuhan industri, kami berkomitmen untuk membekali mahasiswa dengan pengetahuan dan keahlian terkini, serta membentuk karakter, menanamkan jiwa wirausaha, dan membuka gerbang menuju peluang karir global.</p>','<p>Universitas Bakti Tunas Husada (Universitas BTH) adalah institusi pendidikan tinggi yang berdedikasi untuk menciptakan sumber daya manusia yang unggul, inovatif, dan profesional. Berdiri di atas fondasi yang kokoh sejak tahun 1993, kami telah bertransformasi menjadi sebuah universitas komprehensif yang secara unik mengintegrasikan tiga pilar keilmuan strategis: Kesehatan, Teknologi, dan Bisnis.<br><br>Didukung oleh tenaga pendidik ahli, fasilitas modern, dan kurikulum yang relevan dengan kebutuhan industri, kami berkomitmen untuk membekali mahasiswa dengan pengetahuan dan keahlian terkini, serta membentuk karakter, menanamkan jiwa wirausaha, dan membuka gerbang menuju peluang karir global.</p>','YTm5WglY77Pzj2553s9o8SY8RCVi8i8FcOGgIvSg.webp','1Gg1bdKCYPt1u6unmgOYy0DcXeK3URUDzEzoJPJ8.webp','KVBOdL3DUdk',NULL,'2025-10-06 09:21:29');
