INSERT INTO `benefits` VALUES (3,'Peta Potensi dan Bakat','peta-potensi-dan-bakat','<p>Dapatkan gambaran visual tentang potensi dan bakat Anda yang bisa dikembangkan lebih lanjut.&nbsp;</p>',22,NULL,'l1oara9G1uaFD2KCZtsZs8GXU02igdlj03kzizbe.jpg','2025-02-25 00:03:58','2025-02-25 00:09:10'),(4,'Rekomendasi Pendidikan dan Karir','rekomendasi-pendidikan-dan-karir','<p>Rekomendasi jurusan pendidikan dan pilihan karir yang sesuai dengan minat dan kemampuan Anda sehingga dapat memanfaatkan waktu dan materi dengan tepat untuk kesukesan Anda.</p>',22,NULL,'3ascUtEPNe3YHRFoHA46g4NersyAcFZs0CaIA1z8.jpg','2025-02-25 00:08:56','2025-02-25 00:08:56'),(5,'Gambaran Karakter','gambaran-karakter','<p>Pelajari aspek-aspek penting dari kepribadian Anda untuk memahami bagaimana anda berinteraksi dan berperan dengan lingkungan sekitar.</p>',22,NULL,'T0llYNVCZDUd8Hodjq2VvcOtYyqUjUqGHVYVRYPE.jpg','2025-02-25 00:10:59','2025-02-25 00:10:59'),(6,'Mengetahui Kekuatan dan Kelemahan','mengetahui-kekuatan-dan-kelemahan','<p>Identifikasi kekuatan utama dan area yang perlu dikembangkan lebih lanjut.</p>',22,NULL,'yK2HXpHDUHaqWHqHhg9G9ZWorWDSQXca4UGQ4XaW.jpg','2025-02-25 00:12:38','2025-02-25 00:53:46'),(7,'Strategi Memotivasi Diri','strategi-memotivasi-diri','<p>Temukan cara-cara efektif untuk memotivasi diri termasuk bahasa cinta, stress release dan kaliberasi diri yang tepat untuk Anda</p>',22,NULL,'YgCRhar6dBpOob28zITdbfCa47ina4HwX3OuA8D6.jpg','2025-02-25 00:15:30','2025-02-25 00:53:58'),(8,'Pola Asuh','pola-asuh','<p>Dapatkan panduan pola asuh yang sesuai untuk mendukung perkembangan anda / putra-putri Anda secara holistik.</p>',22,NULL,'y1oCXd5ha2BdyW47X8ODpv7Dk98TiOibJ6kJDvuG.jpg','2025-02-25 00:16:42','2025-02-25 00:16:42'),(9,'Pengukuran Kemampuan Kognitif','pengukuran-kemampuan-kognitif','<p>Temukan seberapa baik Anda dalam berbagai area seperti logika, pemahaman, dan pemecahan masalah.</p>',23,NULL,'B7cPc7qMac1QzpBdBtD9yxBVl4HMXg7Sg5przJWY.jpg','2025-02-25 01:03:32','2025-02-25 01:03:32'),(10,'Pengembangan Diri','pengembangan-diri','<p>Pahami kekuatan dan kelemahan intelektual Anda untuk merencanakan pengembangan diri yang lebih baik.</p>',23,NULL,'lWjzBMy9279ehhyqX5nDtCIpoh1M2rxCLIikeGKn.jpg','2025-02-25 01:05:44','2025-02-25 01:05:44'),(11,'Rekomendasi Karir','rekomendasi-karir','<p>Dapatkan wawasan mengenai bidang-bidang yang cocok dengan profil kecerdasan Anda untuk perencanaan karir yang lebih tepat.</p>',23,NULL,'F8jwONmoaT1QAbehxPJg966tVoDD2e4D3siEqO0q.jpg','2025-02-25 01:06:11','2025-02-25 01:06:11'),(12,'Tingkatkan Kepercayaan Diri','tingkatkan-kepercayaan-diri','<p>Mengetahui tingkat IQ Anda dapat meningkatkan rasa percaya diri dan membantu Anda menetapkan tujuan yang lebih realistis.</p>',23,NULL,'TX1xsDRse1C5SmkdZy63MwgSOYA0hztIkSTC7DKH.jpg','2025-02-25 01:06:37','2025-02-25 01:06:37'),(13,'Personalized Learning Experience','personalized-learning-experience','<p>Temukan apakah Anda lebih cenderung belajar secara visual, auditori, atau kinestetik. Dengan memahami gaya belajar Anda, Anda dapat menyesuaikan metode belajar yang paling efektif.</p>',24,NULL,'Ffzpp4C6vrzjKREPsaG4QS0anj8xbPMCmmcDCp3i.jpg','2025-02-25 01:12:30','2025-02-25 01:12:50'),(14,'Peningkatan Kinerja Akademis','peningkatan-kinerja-akademis','<p>Identifikasi teknik belajar yang sesuai dengan gaya Anda untuk meningkatkan pemahaman materi dan prestasi akademis.</p>',24,NULL,'HinofAxPurUUl2DygatynkC6xgjHh4myFnwKr0ss.jpg','2025-02-25 01:13:58','2025-02-25 01:13:58'),(15,'Optimalkan Waktu Belajar','optimalkan-waktu-belajar','<p>Hindari pemborosan waktu dengan metode belajar yang tidak efektif. Dengan gaya belajar yang tepat, Anda dapat belajar lebih cepat dan efisien.</p>',24,NULL,'SCzCj1vxbYc6HmHNDQIc5ZEevs4jMcqn09maKLeP.jpg','2025-02-25 01:14:56','2025-02-25 01:14:56'),(16,'Meningkatkan Kepercayaan Diri','meningkatkan-kepercayaan-diri','<p>Mengetahui gaya belajar Anda dapat membantu meningkatkan rasa percaya diri dan motivasi dalam proses belajar.</p>',24,NULL,'q1WGquMNFTvWisxystJHcd6wLELRpsMpc63eHQ45.jpg','2025-02-25 01:15:40','2025-02-25 01:15:40'),(17,'Strategi Belajar yang Tepat','strategi-belajar-yang-tepat','<p>Dapatkan rekomendasi strategi belajar yang sesuai dengan gaya Anda, sehingga proses belajar menjadi lebih menyenangkan dan produktif.</p>',24,NULL,'PPSp6Y3r8k7SCh1etYXjNCFk87XFM79wjIyWWG39.jpg','2025-02-25 01:16:13','2025-02-25 01:16:13'),(18,'Evaluasi Tingkat Ketergantungan','evaluasi-tingkat-ketergantungan','<p>Tes ini membantu Anda memahami seberapa besar ketergantungan Anda pada gadget dan dampaknya terhadap kehidupan Anda.</p>',25,NULL,'pCrH9eFHNw4es3GRmi1c3Cm2gik7ZcXBySqgal81.jpg','2025-02-25 01:21:30','2025-02-25 01:21:30'),(19,'Kesadaran Diri','kesadaran-diri','<p>Dengan mengetahui tingkat kecanduan Anda, Anda dapat mengambil langkah-langkah untuk mengurangi penggunaan gadget yang berlebihan.</p>',25,NULL,'gdB88Xrh1bgw1wQyqrov7FEX7wACcNlGrVEB0YsI.jpg','2025-02-25 01:22:50','2025-02-25 01:22:50'),(20,'Rekomendasi Praktis','rekomendasi-praktis','<p>Dapatkan saran dan strategi yang efektif untuk mengurangi ketergantungan pada gadget dan meningkatkan kualitas hidup Anda.</p>',25,NULL,'GKZLOXTo46hsdciU6bbSbXJg9nQ8hDpsrkOJvYHZ.jpg','2025-02-25 01:23:38','2025-02-25 01:24:37'),(21,'Dukungan Ahli','dukungan-ahli','<p>Jika diperlukan, dapatkan sesi konsultasi dengan ahli untuk mendiskusikan hasil tes dan rencana tindakan yang sesuai.</p>',25,NULL,'kqqdtBZ9UZVBcsJOw29IJUvfdeBBZTTKfXsoxlK9.jpg','2025-02-25 01:24:21','2025-02-25 01:24:21'),(22,'Psikolog Profesional','psikolog-profesional','<p>Kami bekerja sama dengan psikolog klinis, psikolog pendidikan, psikolog hukum, psikolog keluarga, dan banyak lagi. Dapatkan bantuan dari ahli yang tepat sesuai dengan kebutuhan Anda.</p>',26,NULL,'ngvc7GaImXk4A6A04jrJd8HqUBYUUu9wAx3fCBoF.jpg','2025-02-25 01:30:00','2025-02-25 01:30:00'),(23,'Peer Counselling','peer-counselling','<p>Selain konsultasi dengan psikolog profesional, kami juga menawarkan layanan peer counselling untuk memberikan dukungan emosional dan pemahaman dari sesama.</p>',26,NULL,'3nDGx7M8TrvEkXiD4Otf6eJ5C1tTlid2volDMKFX.jpg','2025-02-25 01:31:12','2025-02-25 01:31:12'),(24,'Privasi dan Keamanan','privasi-dan-keamanan','<p>Hallopsy memastikan semua sesi konsultasi dilakukan dengan privasi penuh dan keamanan data yang tinggi. Anda bisa berbicara dengan tenang tanpa khawatir tentang kerahasiaan informasi Anda.</p>',26,NULL,'UUnQQjwFW1EjcV99x1v7JxNXEkk0YMT0Dgm8T41R.jpg','2025-02-25 01:31:58','2025-02-25 01:31:58'),(25,'Akses Mudah dan Fleksibel','akses-mudah-dan-fleksibel','<p>Konsultasi dapat dilakukan dari mana saja dan kapan saja. Cukup dengan perangkat yang terhubung ke internet, Anda bisa mendapatkan bantuan yang Anda butuhkan tanpa harus keluar rumah.</p>',26,NULL,'YCjGbAWooZt4V1B1JdVlckgJRdrjRn1sRMAnK25Q.jpg','2025-02-25 01:33:15','2025-02-25 01:33:15'),(26,'Pendekatan Holistik','pendekatan-holistik','<p>Hallopsy mengedepankan pendekatan yang holistik dalam penanganan masalah, memastikan Anda mendapatkan dukungan yang menyeluruh dan terintegrasi.</p>',26,NULL,'FvsQcB4TzIpqRx4plnLkvMSgq9NERWtnDPcPAM3Z.jpg','2025-02-25 01:34:47','2025-02-25 01:34:47');
/*!40000 ALTER TABLE `benefits` ENABLE KEYS */;
UNLOCK TABLES;

