d><p>&nbsp;</p><p>&nbsp;</p></td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr></tbody></table></figure><p>Lab Komputer Multimedia</p><p>&nbsp;</p><p>&nbsp;</p><p>&nbsp;</p><p>&nbsp;</p><p>&nbsp;</p><p>&nbsp;</p><figure class=\"table\"><table><tbody><tr><td>&nbsp;</td><td><p>&nbsp;</p><p>&nbsp;</p></td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr></tbody></table></figure><p>Lab Komputer Multimedia</p>','8rQMNm6lDCAzSlakCTKRvNPDbUYJGzbjDXtIszNv.webp','VB96FD7kWJlP4B9jCAiOzv56FDb0Cq3f2iyV7oJd.webp','ouZ6BBUC4ZJsH4BTKhsUM9x0EnUakF4OQ8Au4eVa.webp','19Cuvp3q9Vh2ue2vzoaEKPjWtQZt4aYZLzdPqfgX.webp','glwdF9DBB9jLKuiQLYIh1MkwgsAbhdnnNYDjEvxJ.webp',NULL,NULL,NULL,'2025-10-01 11:18:32','2025-10-02 15:25:24'),(114,58,'Laboratorium Keperawatan Medikal-Bedah (KMB)','laboratorium-keperawatan-medikal-bedah-kmb','Laboratorium Keperawatan Medikal-Bedah (KMB)','<p>Melatih mahasiswa dalam keterampilan dasar dan lanjutan keperawatan medikal-bedah, khususnya kasus kardiovaskuler.<br>Peralatan: Patient simulator, manekin perawatan luka &amp; injeksi, ECG trainer, monitor tanda vital digital, alat oksigenasi, dan peralatan infus modern.<br>&nbsp;</p>','NYC6o5pNYrFXFczf1cVMH4BudjzboW59qGCnCVil.jpg',NULL,NULL,NULL,NULL,NULL,1,1,'2025-10-04 09:53:26','2025-10-04 09:54:02'),(115,69,'Laboratorium Multimedia','laboratorium-multimedia',NULL,'<p>Laboratorium Multimedia</p>','fNKJSw6WgEmodwSVq45EzsTbsNk8DPYTEbgPdPQJ.jpg',NULL,NULL,NULL,NULL,NULL,1,1,'2025-10-04 09:56:05','2025-10-04 09:56:05'),(116,58,'Laboratorium Keperawatan Gawat Darurat & Kritis (Emergency & Critical Care Lab)','laboratorium-keperawatan-gawat-darurat-kritis-emergency-critical-care-lab','Laboratorium Keperawatan Gawat Darurat & Kritis (Emergency & Critical Care Lab)','<p>Simulasi penanganan pasien gawat darurat dan kritis.<br>Peralatan: Ambu bag, defibrillator trainer, monitor ICU, intubation set, trauma kit, serta simulator CPR untuk Basic Life Support (BLS) dan Advanced Cardiac Life Support (ACLS).</p>','cNitnzVJyFqfKTKrLzKGrpwu9orSuKLU0lbXUtnb.jpg',NULL,NULL,NULL,NULL,NULL,1,1,'2025-10-04 09:57:38','2025-10-04 09:58:46'),(117,58,'Laboratorium Keperawatan Maternitas & Anak','laboratorium-keperawatan-maternitas-anak','Laboratorium Keperawatan Maternitas & Anak','<p>Praktik asuhan keperawatan ibu hamil, bersalin, nifas, bayi baru lahir, dan anak.<br>Peralatan: Manekin persalinan (birthing simulator), manekin bayi &amp; anak, fetal doppler, incubator bayi, dan phantom pemeriksaan kehamilan.<br>&nbsp;</p>','CQnNlGxeZqtyqqEXmESd4IKlfjqFXQwIArfGMaWK.jpg',NULL,NULL,NULL,NULL,NULL,1,1,'2025-10-04 10:02:07','2025-10-04 10:02:07'),(118,58,'Laboratorium Keperawatan Jiwa','laboratorium-keperawatan-jiwa','Laboratorium Keperawatan Jiwa','<p>Tempat latihan komunikasi terapeutik, role play, dan konseling pasien dengan masalah kejiwaan.<br>Peralatan: Role-play room dengan CCTV untuk observasi, ruang konseling kedap suara, serta perangkat rekam audio-video untuk evaluasi komunikasi.<br>&nbsp;</p>','xxgJbzvuwx4zJMVrqIKmzwUrRCAbOOSc6qsUrp36.jpg',NULL,NULL,NULL,NULL,NULL,1,1,'2025-10-04 10:03:24','2025-10-04 10:03:24'),(119,58,'Laboratorium Keperawatan Komunitas & Keluarga','laboratorium-keperawatan-komunitas-keluarga','Laboratorium Keperawatan Komunitas & Keluarga','<p>Simulasi kegiatan promosi kesehatan, kunjungan rumah, serta program intervensi berbasis komunitas.<br>Peralatan: Home care kit, alat pemeriksaan kesehatan dasar (tensi digital, glucometer, stethoscope set), serta media edukasi digital untuk promosi kesehatan.</p>','mtrbn9hpFHEneaaTwsJTBqWcoZGqtrjbwFgHVxia.jpg',NULL,NULL,NULL,NULL,NULL,1,1,'2025-10-04 10:05:03','2025-10-04 10:05:03'),(120,58,'Laboratorium Keperawatan Gerontik','laboratorium-keperawatan-gerontik','Laboratorium Keperawatan Gerontik','<p>Latihan keterampilan perawatan lansia dengan fokus pada penyakit degeneratif (terutama kardiovaskuler dan hipertensi).<br>Peralatan: Gerontological aging simulator suit (alat yang meniru kondisi fisik lansia), kursi roda elektrik, alat bantu jalan, serta rehabilitation ki</p>','Nl6B7WP876zCOxCf6mcrD2S8IhBjt7rCyFXt5fyX.jpg',NULL,NULL,NULL,NULL,NULL,1,1,'2025-10-04 10:06:35','2025-10-04 10:06:35'),(121,58,'Laboratorium Manajemen Keperawatan','laboratorium-manajemen-keperawatan','Laboratorium Manajemen Keperawatan','<p>Melatih mahasiswa dalam pengelolaan unit layanan, kepemimpinan, dan mutu pelayanan keperawatan.<br>Peralatan: Miniatur nurse station, software sistem informasi manajemen rumah sakit (SIMRS) versi simulasi, serta perangkat komputer untuk praktik manajemen.</p>','8QLhwW0AIdhGodI6Qmx7bf0QSHaGNcuiHsVFTaHf.jpg',NULL,NULL,NULL,NULL,NULL,1,1,'2025-10-04 10:08:24','2025-10-04 10:08:24'),(122,58,'Laboratorium Keperawatan Kardiovaskuler','laboratorium-keperawatan-kardiovaskuler','Laboratorium Keperawatan Kardiovaskuler','<p>Laboratorium ini menjadi center of excellence PSPPN UBTH, tempat mahasiswa berlatih keterampilan spesifik dalam asuhan keperawatan pasien dengan penyakit jantung dan pembuluh darah. Laboratorium ini mendukung praktik berbasis evidence dalam penanganan kasus kardiovaskuler, mulai dari pencegahan, deteksi dini, tindakan keperawatan akut, hingga rehabilitasi pasien.</p>','FD4yvrp350rsIpcFW9BVCrSrf70nw5dYSGjquRHb.jpg',NULL,NULL,NULL,NULL,NULL,1,1,'2025-10-04 10:11:00','2025-10-04 10:11:00'),(123,64,'Laboratorium Formulasi','laboratorium-formulasi','Laboratorium Formulasi','<p>Laboratorium Formulasi</p>','uxLMtPW5aalrfm6wicvoLtnHvc5xanV0XaVPrh7B.jpg',NULL,NULL,NULL,NULL,NULL,1,1,'2025-10-04 10:19:06','2025-10-04 10:30:05'),(124,64,'Bahan alam','bahan-alam','Bahan alam','<p>&nbsp;Bahan alam</p>','j7hQXK5KnFc5k7rUuA6RLqTPEDtP6uJyUdOCDBXT.jpg',NULL,NULL,NULL,NULL,NULL,1,1,'2025-10-04 10:22:57','2025-10-04 10:22:57'),(125,64,'Laboratorium Kimia','laboratorium-kimia','Laboratorium Kimia','<p>Laboratorium Kimia</p>','Na6XjEb0ySRYGd3NDJ2XEgiGmq8UHwwYAp439hoR.jpg',NULL,NULL,NULL,NULL,NULL,1,1,'2025-10-04 10:25:52','2025-10-04 10:25:52'),(126,64,'farmakologi','farmakologi','farmakologi','<p>