INSERT INTO `fakultas` VALUES (21,'Fakultas Kesehatan','fakultas-kesehatan','\" Membentuk Tenaga Kesehatan Profesional, Humanis, dan Berdaya Saing Global \"','https://youtube.com/@s1keperawatan_universitasbth?si=ccxnn9bmr4ta3h0_',114,'Fakultas Kesehatan','<p>Program Studi Sarjana Keperawatan&nbsp; Fakultas Ilmu Kesehatan Universitas Bakti Tunas Husada &nbsp;&nbsp;merupakan program pendidikan tinggi jenjang sarjana yang bertujuan menghasilkan untuk menghasilkan tenaga keperawatan profesional yang unggul, inovatif, dan berdaya saing nasional, khususnya dalam bidang keperawatan kardiovaskular. Program ini mengintegrasikan teori dan praktik keperawatan secara mendalam, berlandaskan etika akademik dan budaya mutu, untuk memenuhi kebutuhan layanan kesehatan modern yang berfokus pada penyakit kardiovaskular.</p>','150','0','0','3','univ-bth','https://www.instagram.com/sarjanakeperawatan.bth?igsh=MXVveHUydDV0Zmp4Mg==','univ-bth',NULL,NULL,'admisi@universitas-bth.ac.id','082117100200','<p>Mugarsari, Kec. Tamansari, Kab. Tasikmalaya, Jawa Barat 46196, Indonesia</p>',NULL,'Kesehatan Universitas BTH','<p>Program Studi Sarjana Keperawatan&nbsp; Fakultas Ilmu Kesehatan Universitas Bakti Tunas Husada &nbsp;&nbsp;merupakan program pendidikan tinggi jenjang sarjana yang bertujuan menghasilkan untuk menghasilkan tenaga keperawatan profesional yang unggul, inovatif, dan berdaya saing nasional, khususnya dalam bidang keperawatan kardiovaskular. Program ini mengintegrasikan teori dan praktik keperawatan secara mendalam, berlandaskan etika akademik dan budaya mutu, untuk memenuhi kebutuhan layanan kesehatan modern yang berfokus pada penyakit kardiovaskular.</p>','Fakultas & Program Studi Masa Depan','<ol><li>1. Menyelenggarakan pendidikan di bidang keperawatan dengan menerapkan budaya mutu berlandaskan etika akademik dengan keunggulan keperawatan kardiovaskuler&nbsp;<br>2. Menyelenggarakan penelitian keperawatan berbasis keperawatan kardiovaskuler dan ilmu keperawatan lainnya yang mendukung.<br>3. Menyelenggarakan pengabdian kepada masyarakat yang berbasis hasil penelitian untuk pemecahan masalah kesehatan kardiovaskuler dan masalah kesehatan lainnya yang berkembang di masayarakat<br>4. Menyelenggarakan kerjasama kemitraan dengan berbagai pemangku kepentingan di dalam dan luar negeri dalam peningkatan kegiatan tridharma perguruan tinggi<br>&nbsp;</li></ol>','BUEhiflsVcnnoec1CTIDkPWJZAfmDXgcPODa9ybT.jpg','n2NLBZpbEt12omqaVU2ArVWwweDWLOCgIJSHbPtQ.jpg','bdBFIvKUlwuVOY3YxA1wvJFZmBAmUIb8BSQbOKet.webp','5egYy7XjkSZfhMUZ7qlvceLuNx3Tk3HuU2V0joN3.webp',NULL,'Link Fakultas','#000000','2025-09-25 13:51:50','2025-10-07 15:01:35'),(26,'Fakultas Farmasi','fakultas-farmasi','Akreditasi program studi S1 Farmasi status terakreditasi dengan peringkat baik sekali','https://youtu.be/jPnLmF5-6VA?si=g3LycBdryeBkDTf2',32,'Farmasi Universitas BTH','<p>Lulusan program studi ini diarahkan untuk menciptakan sarjana yang profesional dibidang farmasi. Bidang Keilmuan Farmasi ini terdiri dari 5 bagian yaitu Kimia Farmasi, Teknologi Formulasi, Bahan Alam Farmasi, Farmakologi dan Ilmu Dasar/Tambahan lainnya. Ilmu – ilmu tersebut merupakan ilmu yang berhubungan atau kelompok keilmuan dan terapan dibidang farmasi. Sistem ini meliputi teori, praktek dan penelitian. Lulusan program studi ini dapat melanjutkan pendidikan berikutnya untuk menjadi apoteker atau melanjutkan jenjang S2 Farmasi.</p>','1073','196','31','1','@farmasi','https://www.instagram.com/farmasi.bth?utm_source=ig_web_button_share_sheet&igsh=MXVpdmU1dmJ2dHN0eg==)','@farmasi','https://youtu.be/jPnLmF5-6VA?si=g3LycBdryeBkDTf2',NULL,'farmasi@universitas-bth.ac.id','085223668983 (prodi)','<p>Jl. Letjen Mashudi No.20, Setiaratu, Kec. Cibeureum, Kab. Tasikmalaya, Jawa Barat 46196, Indonesia</p>',NULL,'Fakultas & Program Studi Masa Depan','<p>Lulusan program studi ini diarahkan untuk menciptakan sarjana yang profesional dibidang farmasi. Bidang Keilmuan Farmasi ini terdiri dari 5 bagian yaitu Kimia Farmasi, Teknologi Formulasi, Bahan Alam Farmasi, Farmakologi dan Ilmu Dasar/Tambahan lainnya. Ilmu – ilmu tersebut merupakan ilmu yang berhubungan atau kelompok keilmuan dan terapan dibidang farmasi. Sistem ini meliputi teori, praktek dan penelitian. Lulusan program studi ini dapat melanjutkan pendidikan berikutnya untuk menjadi apoteker atau melanjutkan jenjang S2 Farmasi.</p>','Fakultas & Program Studi Masa Depan','<p>a. Menyelenggarakan pendidikan farmasi yang unggul berdasarkan etika akademik, spirit pharmapreneur, inovatif dan berdaya saing global dalam kewirausahaan produk farmasi&nbsp;<br>b. Menyelenggarakan kegiatan penelitian yang berbasis kewirausahaan produk farmasi<br>c. Menyelenggarakan kegiatan pengabdian masyarakat yang berbasis kewirausahaan produk farmasi<br>d. Meningkatkan aktivitas kerjasama nasional dan internasional dalam upaya pelaksanaan tridarma Peguruan Tinggi<br><br>&nbsp;</p>','AoOeG6VI371uBCuVlvA7tPKAjAmGxXFARGniPmGV.jpg','cxmBQu8gHjBzuJVfBZDdqVrFGf6bVvkpjgeVwdlU.jpg','owBcSt1kbWlepOJQlXAX9VcDTsPt2NQJYBC2xe2v.jpg','hRbShn5cVIL3PTS08XHcGpW2MeeKI7pcBL0k8QEI.jpg','wQnVSw9cpy9SJOv0cBqaAZslSAu4UDlGjzqsWUiE.jpg','Link Fakultas','#000000','2025-09-26 15:22:55','2025-10-07 15:45:02'),(27,'Fakultas Teknologi dan Bisnis','fakultas-teknologi-dan-bisnis','Bridging Technology and Business for Global Impact',NULL,218,'Fakultas Teknologi dan Bisnis','<p>Fakultas Teknologi dan Bisnis (FTB) Universitas Bakti Tunas Husada (UBTH), berdiri 15 Desember 2021, menyelenggarakan pendidikan, penelitian, dan pengabdian masyarakat di bidang Bisnis Digital, Kewirausahaan, Teknologi Pangan, dan Sistem Informasi. Saat ini mengelola tiga program studi S1 (Bisnis Digital, Kewirausahaan, Teknologi Pangan) dengan akreditasi minimal B, serta berkomitmen meningkatkan kualitas, kinerja, reputasi, dan keberlanjutan sesuai kebutuhan stakeholder dan regulasi.</p>',NULL,NULL,'16',NULL,NULL,'https://www.instagram.com/ftb.bth?igsh=ZDl3Zng3OTN5NXJt',NULL,NULL,NULL,'ftb@universitas-bth.ac.id','081321374485','<p>Jl. Letjen Mashudi No.20, Setiaratu, Kec. Cibeureum, Kab. Tasikmalaya, Jawa Barat 46196, Indonesia</p>',NULL,'Teknologi dan Bisnis Universitas BTH','<p>Fakultas Teknologi dan Bisnis (FTB) Universitas Bakti Tunas Husada (UBTH), berdiri 15 Desember 2021, menyelenggarakan pendidikan, penelitian, dan pengabdian masyarakat di bidang Bisnis Digital, Kewirausahaan, Teknologi Pangan, dan Sistem Informasi. Saat ini mengelola tiga program studi S1 (Bisnis Digital, Kewirausahaan, Teknologi Pangan) dengan akreditasi minimal B, serta berkomitmen meningkatkan kualitas, kinerja, reputasi, dan keberlanjutan sesuai kebutuhan stakeholder dan regulasi.</p>','Fakultas & Program Studi Masa Depan','<ol><li>(1) Meningkatkan Kualitas Penyelenggaraan Tridarma<br>Perguruan Tinggi Berbasis 10 nilai dasar Universitas BTH dalam Bidang teknologi<br>dan Bisnis secara Terintegrasi dan Inovatif</li><li>(2) Meningkatkan Kompetensi dan<br>Profesionalisme SDM dalam Bingkai berakhlak mulia</li><li>(3) Menyelenggarakan Tata<br>Kelola Pendidikan yang Profesional dan Akuntabel</li><li>&nbsp;(4) Melaksanakan Kerjasama<br>Strategis dengan Berbagai Pihak, baik dalam Skala Nasional, Regional maupun<br>Internasional</li></ol>','MGT98nWJbWGxN2PP5JLtv3RccOfXMXzsx0JwmNvW.jpg','ZOJH669Ww1MqBpCH81lTGveLKW3xrvAsPSXa2uB4.jpg','ODp2hyhQBZ5tIwww8yzLw1ZVIUew2kYePnQdMCkK.jpg',NULL,'JCJt8kL2ZD9Ga1d1kkJBbeu8csR4aroZSFyuVuGc.jpg','Link Fakultas','#000000','2025-09-26 15:42:39','2025-10-07 14:59:01');
