INSERT INTO `identities` VALUES (1,'Universitas Bakti Tunas Husada','2025','Senin - Jumat','08.00 - 16.00','<p>Universitas Bakti Tunas Husada (UBTH) - Perguruan Tinggi Swasta terkemuka di Tasikmalaya, Jawa Barat, yang menyediakan berbagai program studi berkualitas untuk jenjang Diploma, Sarjana, Magister.</p>','<p>Jl. Letjen Mashudi No.20, Setiaratu, Kec. Cibeureum, Kab. Tasikmalaya, Jawa Barat 46196</p>','https://maps.app.goo.gl/WzG6qkpbtAMtG7Ar7','6282117100200','info-pmb@universitas-bth.ac.id','universitas.bth','universitas.bth','universitas.bth','Universitas BTH','NHjHJKIfCenRUC5wE7HTtnTQqd5GvY9Q9gm7L3k4.png','oj3LPEDF4ZwDMVwwUjWRmUkkDetBa8s5q0pX6a8N.png',NULL,'2025-10-11 05:13:20');
