INSERT INTO `infodaftars` VALUES (1,'Daftar Sekarang di Al Lathif Islamic School','Menyongsong Pendidikan Berkualitas Berlandaskan Nilai-Nilai Islami','<p>Tempat di mana setiap anak memiliki kesempatan untuk menggali potensi mereka secara optimal dan menanamkan nilai-nilai yang akan membentuk masa depan yang berkarakter.&nbsp;</p>','<h3><strong>Investas Pendidikan Sangat Terjangkau</strong></h3><p>Dengan begitu banyak manfaat yang di dapat, Investasi Pendidikan di Al Lathif Islamic School. insya Allah <strong>SANGAT TERJANGKAU. </strong>Bagi Ananda yang memiliki <strong>prestasi </strong>silahkan untuk mengakses <strong>Penerimaan Murid Baru Jalur Beasiswa Prestasi Akdemik dan Hafidz Qur\'an </strong>dengan menghubungi: <strong>0813-2259-5640 (Mr. Dahawanen)</strong></p><p>Berikut adalah detail investasi:</p>','<p>Bergabunglah dengan kami di Al Lathif Islamic School, di mana setiap hari adalah kesempatan baru untuk tumbuh dan berkembang dalam suasana yang penuh cinta dan dukungan. Mari bersama-sama menciptakan masa depan yang cerah dan bermakna untuk generasi masa depan kita.</p>',NULL,'2025-02-10 23:41:06');
/*!40000 ALTER TABLE `infodaftars` ENABLE KEYS */;
UNLOCK TABLES;

