INSERT INTO `misis` VALUES (1,'Misi dan Tujuan Universitas BTH','2024-2029','<h4><strong>Misi Universitas BTH</strong></h4><p>Menyelenggarakan dan mengembangkan pendidikan tinggi akademik, profesi, dan vokasi di bidang kesehatan, teknologi dan bisnis dengan menerapkan budaya mutu berlandaskan etika akademik, spirit entrepreneurship, berwawasan masa depan, dan <strong>berdaya saing global</strong>.<br><br>Menyelenggarakan dan mengembangkan penelitian unggulan dan penelitian terapan di bidang<strong> kesehatan, teknologi, dan bisnis</strong> serta mendorong pengembangan inovasi berkelanjutan berdasarkan pendekatan pentahelix.<br><br>Menyelenggarakan pengabdian kepada masyarakat yang berbasis hasil penelitian, berbasis pemanfaatan teknologi informasi komunikasi serta berfokus pada pengembangan ekosistem kewirausahaan sivitas akademika dan masyarakat. Mengembangkan kerjasama kemitraan dengan berbagai pemangku kepentingan di dalam maupun di luar negeri dalam upaya akselerasi menuju perguruan tinggi bereputasi nasional dan global</p><h4><strong>Tujuan</strong></h4><ul><li>Menjadikan Universitas BTH sebagai perguruan tinggi yang terkemuka dengan reputasi nasional-internasional dengan</li><li>Menghasilkan lulusan yang berakhlak mulia, berkarakter entrepreneur, kreatif, inovatif dan berdaya saing.</li><li>Menghasilkan karya-karya penelitian yang dapat diimplementasikan untukpengembangan IPTEKS.</li><li>Menghasilkan kegiatan pengabdian kepada masyarakat yang berwawasan IPTEKS dan bermanfaat untuk peningkatan kesejahteraan masyarakat.</li><li>Mewujudkan kerjasama yang strategis, sinergis dan berkelanjutan dengan para mitra perguruan tinggi.</li></ul>','Jegm2cYoarALOJVmzZaDCUra6AYF8uBbIyJh5EL3.webp',NULL,'2025-09-26 15:51:27');
/*!40000 ALTER TABLE `misis` ENABLE KEYS */;
UNLOCK TABLES;

