INSERT INTO `prestasis` VALUES (566,'Karate Juara 3','juara-3-karate','Juara 3 Karate',3,57,1,1,'T7J5CHUsj5yp4kZ45jbbEWFZCnRXgpgTl6pbD0do.webp','2025-09-24','2025-09-26 13:26:49','2025-10-02 14:37:27'),(567,'TEEP Research Inter di Defartement of Fragrance and cosmetic Science Kaoshiung Medical Unuvesity','seina-lathifa-subagja','SEINA LATHIFA SUBAGJA',1,64,1,1,'UaBwad1j0W93SglRCtPhnXee90tJgYBBviquTUuU.webp','2025-02-06','2025-09-26 14:59:19','2025-10-02 14:37:09'),(568,'Nominasi 11 besar finalis PMIA (Panah Merah Inovation Awards) 2022','tim-saynori-dina-aulia-reni-harningsih-dan-fadhiya-munggarani','Tim SAYNORI (Dina Aulia, Reni Harningsih, dan Fadhiya Munggarani)',2,62,1,1,'AR8b5f4Hl9iwMxlaCCMHNjjQ6ePCqK8yXIeeW8hp.webp','2022-01-01','2025-09-26 16:46:07','2025-10-07 09:13:11'),(569,'MAHASISWA PENERIMA BEASISWA JFLS SHORT COURSE 2024','wayan-setiawan','Wayan Setiawan',3,62,1,1,'PpGUJWAcb3Y89IyEJZEwo1poH3QOqDc8IwLhWIoF.jpg','2024-01-01','2025-09-26 18:54:49','2025-10-07 09:12:43'),(570,'Dosen Penerima Hibah Penelitian','ibu-maerani-ssi-msi','Ibu Maerani S.Si., M.Si.',3,62,NULL,NULL,'hxr6eyMT3qBZSR0y4PbdiEeiHgobg9d7qknFqYZV.png',NULL,'2025-10-04 11:50:29','2025-10-04 11:50:29'),(571,'Dosen Penerima Hibah Penelitian','bapak-hadi-yusuf-faturochman-st-msi','Bapak Hadi Yusuf Faturochman, ST., M.Si.',3,62,NULL,NULL,'bwAYOCAQsOTIaLx97yMn9uLjxd2gHR8MuiuUfpjA.png',NULL,'2025-10-04 11:51:32','2025-10-04 11:51:32'),(572,'Dosen Pembimbing Lapangan (DPL) Kampus Mengajar angkatan 7','ibu-maerani-ssi-msi-dan-bapak-hadi-yusuf-faturochman-st-msi','Ibu Maerani, S.Si., M.Si dan Bapak Hadi Yusuf Faturochman, ST., M.Si.',3,62,NULL,NULL,'nwusCjW0JgB355KhZcCRWCS2UKBqjZ7uo4SkYzvg.png',NULL,'2025-10-04 11:52:09','2025-10-04 11:52:09');
