INSERT INTO `pricings` VALUES (1,'School Starter','school-starter','<ul><li>Cek gaya belajar</li><li>Cek kecanduan gadget</li><li>Akun siswa</li></ul>','11','50','30','2025-02-24 15:31:31','2025-02-24 17:04:11'),(2,'School Advances','school-advances','<ul><li>Tes pemetaan talent dan karakter</li><li>Tes IQ</li><li>Tes gaya belajar</li><li>Tes kecanduan gadget</li><li>Akun Siswa</li><li>Akses layanan HalloPsy 10 sesi (minimal tes 200 siswa)</li></ul>','11','200','30','2025-02-24 17:03:45','2025-02-24 17:04:29'),(3,'School Ultimate','school-ultimate','<ul><li>Tes pemetaan talent dan karakter</li><li>Tes IQ</li><li>Tes gaya belajar</li><li>Tes kecanduan gadget</li><li>Tes kebahagiaan</li><li>Akun private per siswa</li><li>Executive Dashboard khusus bagi BK dan Kepala Sekolah</li><li>Akses layanan HalloPsy 10 sesi (minimal tes 200 siswa)</li></ul>','11','350','30','2025-02-24 17:06:40','2025-02-24 17:07:07');
