/*!40000 ALTER TABLE `prosedurs` DISABLE KEYS */;
INSERT INTO `prosedurs` VALUES (1,'Prosedur Pendaftaran','<p>Ayah/Bunda/Anda, terimakasih telah memilih Al Lathif Islamic School menjadi bagian dari tujuan pendidikan Ananda. Semoga Allah Swt memberikan pilihan yang terbaik. Berikut adalah langkah-langkah pendaftaran di Al Lathif Islamic School untuk Preschool (TK), Primary School (SD), Secondary School (SMP &amp; SMA), dan Program Tahfidz Takhasus:</p><h4>Langkah 1: Mengisi Formulir Pendaftaran</h4><p>Pendaftaran ini untuk memastikan bahwa putra/putri Anda tercatat pada urutan pendaftaran.</p><p><a href=\"admisi.allathif.sch.id\">FORMULIR PENDAFTARAN</a></p><h4>&nbsp;</h4><h4>Langkah 2: Membayar Investasi Pendidikan</h4><p>Membayar investasi pendidikan minimal sebesar<strong> 20%</strong> dari <strong>total investasi pendidikan</strong> untuk umum atau <strong>investasi awal </strong>untuk program beasiswa. Pembayaran bisa ditransfer langsung ke rekening Al Lathif Islamic School / Yayasan Noor Rakhmah. Mohon pastikan rekening tujuan pengiriman adalah sebagai berikut:</p><p>Pemilik Rekening:</p><p><strong>Yayasan Noor Rakhmah Al-Lathif</strong></p><p>Nama Bank:</p><p><strong>Bank Syariah Indonesia (Kode Transfer: 451)</strong></p><p>Nomor Rekening:</p><p><strong>686.354.6410</strong></p><p>Jika tidak melanjutkan untuk mendaftar di AIS atau gugur dalam seleksi, maka seluruh dana investasi pendidikan yang telah dibayarkan akan dikembalikan kecuali biaya pendaftaran dan tes psikologi.</p><blockquote><p>Hati-hati terhadap penipuan yang mengatas namakan AIS. Kami hanya menggunakan rekening pendaftaran yang tercantum di atas.</p><p>&nbsp;</p></blockquote><h4>Langkah 3: Mengirimkan Bukti Pembayaran</h4><p>Bukti pembayaran dapat dikirim ke WhatsApp: <strong>0811-2311-369</strong></p><p>&nbsp;</p><h4>Langkah 4: Melakukan Psikotes</h4><p>Tes dilakukan oleh tim psikologi AIS. Tes ini bertujuan untuk mengetahui minat, bakat, dan karakter para calon siswa/siswi dan sebagai pertimbangan bagi para guru dalam melakukan proses pendidikan. Jadwal psikotes akan diinformasikan melalui kontak informasi orang tua/siswa yang telah terdaftar.</p><p>&nbsp;</p><h4>Langkah 5: Melakukan Registasi Ulang</h4><ul><li>Ananda yang telah mendaftar dan lolos psikotes atau seleksi beasiswa akan mendapatkan pemberitahuan untuk melakuakn registrasi ulang. Berikut adalah data yang harus dilengkapi pada saat registrasi ulang:</li><li>Formulir registrasi ulang</li><li>Scan / Fotokopi ijazah terakhir</li><li>Pas foto ukuran 3 x 4</li><li>Scan/fotokopi akte lahir</li><li>Scan/fotokopi kartu keluarga</li><li>Scan / Fotokopi penghargaan yang pernah diperoleh</li><li>Bukti pelunasan dana investasi pendidikan</li></ul><p>Para siswa/siswi yang telah melakukan registrasi ulang akan mendapatkan nomor induk siswa dan mendapatkan perlengkapan sekolah (seragam, tas, buku, dll)</p><p>&nbsp;</p>','XepI5n00HwrtdYmmA91qDEFONBrcMZTOnQqRFZhK.jpg',NULL,'2025-02-11 04:59:14');
/*!40000 ALTER TABLE `prosedurs` ENABLE KEYS */;
UNLOCK TABLES;

