INSERT INTO `sliders` VALUES (28,'Buka Kunci Masa Depanmu Sekarang! Gelombang 1 Resmi Dibuka!','buka-kunci-masa-depanmu-sekarang-gelombang-1-resmi-dibuka',64,'7Tr4gJNooCvIgvfVjSrqzzhWvMxNIhBAxdzNp7BY.webp','0CCQcycUQlG2FhTUvs9N85Qx4NjVaLY20tKWFTIK.webp','<p>Peluang diterima paling besar ada di sini.<br>Lupakan cemas dan drama menunggu. Mendaftar di gelombang pertama adalah langkah cerdas untuk mengamankan program studi impian dan membuka peluang beasiswa terbaik. Kenapa harus menunggu kalau bisa tenang dari sekarang?</p>',NULL,'DAFTAR SEKARANG','http://pendaftaran.universitas-bth.ac.id/',NULL,1,'2025-09-25 12:08:36','2025-10-06 09:29:52');
/*!40000 ALTER TABLE `sliders` ENABLE KEYS */;
