INSERT INTO `stories` VALUES (1,'RA Al Lathif','ra-al-lathif','<p>RA Al Lathif merupakan cikal bakal dari Islamic Preschool. Lembaga pendidikan formal anak usia dini dibawah kementrian agama RI</p>','2001','JbIHF6qfruVRR8rqHEyUIr2DO4axn50to4XaaFm6.jpg','2023-12-18 20:26:10','2023-12-19 03:57:40'),(2,'Al Lathif Islamic Preschool','al-lathif-islamic-preschool','Merupakan sekolah untuk anak usia dini dengan kurikulum Islam yang dipadukan dengan kurikulum internasional.','2009','fUr8JVLpIDcoGmrfBtdiH79Tx1Q1Uf42nsKBnoig.jpg','2023-12-19 03:59:16','2023-12-19 03:59:16'),(3,'Al Lathif Islamic Primary School (SD)','al-lathif-islamic-primary-school-sd','Merupakan pendidikan tingkat SD untuk memberikan fondasi yang kuat dalam membentuk generasi muslim yang berwawasan global.','2012','Tn0wvAYAIoMNgD0LPb9H4eSI1jcYVbemWLgmzLCv.jpg','2023-12-19 04:09:30','2023-12-19 04:09:30'),(4,'Al Lathif Islamic Secondary School (SMP)','al-lathif-islamic-secondary-school-smp','<p>Sekolah tingkat menengah pertama yang didirakan untuk membentuk generasi muslim dengan akidah yang kokoh, berakhlak mulia dan memiliki komptensi yang diakui secara internasiona (IGCSE)</p>','2018','3zFosmqm5Gcheqpu7L4fxHz6bPEYezhWnNAWcPGH.jpg','2023-12-19 04:12:00','2023-12-19 04:15:06'),(5,'Al Lathif Upper Secondary School (SMA)','al-lathif-upper-secondary-school-sma','<p>Pendidikan setingkat SMA untuk memersiapkan para kader dakwah dan generasi yang mampu membuat karya bermanfaat dan memiliki kompetensi yang diakui dunia internasional (Cambridge A/AS Level)</p>','2020','h4CgYubR4idyTTAunLUKfMpp5vTsmOTReDORnaZM.jpg','2023-12-19 04:14:49','2023-12-19 04:17:38'),(6,'Tahfidz Takhasus Program','tahfidz-takhasus-program','Program khusus bagi para siswa tingkat SMP/SMA untuk belajar Hafidz Qur\'an','2022','pciwpqrNVtmB5YzGMeuZrnVxQHfplYd5bILZ0QqK.jpg','2023-12-19 04:19:13','2023-12-19 04:19:13');
/*!40000 ALTER TABLE `stories` ENABLE KEYS */;
