INSERT INTO `unggulans` VALUES (352,'Keunggulan Kardiovaskuler','keunggulan-kardiovaskuler','1758874139.jpg','<p>Fokus utama pada keperawatan kardiovaskuler sebagai center of excellence, membekali mahasiswa dengan kompetensi spesifik yang dibutuhkan di era meningkatnya kasus penyakit jantung.<br><br>&nbsp;</p>',NULL,58,NULL,1,'2025-09-26 15:08:59','2025-10-03 16:37:27'),(353,'Kurikulum Terkini & Relevan','kurikulum-terkini-relevan','1758874790.jpg','<ol><li>Prodi dirancang berbasis bisnis kreatif, pemasaran digital, dan kewirausahaan, sehingga selaras dengan kebutuhan dunia industri dan perkembangan teknologi terbaru.<br><br>&nbsp;</li></ol>',NULL,68,NULL,1,'2025-09-26 15:19:50','2025-10-04 08:45:38'),(354,'Kurikulum Unggul & Berdaya Saing Global','kurikulum-unggul-berdaya-saing-global','1758875401.jpg','<ol><li>Kurikulum disusun berdasarkan etika akademik dengan spirit pharmapreneur, inovatif, dan selaras dengan kebutuhan industri farmasi modern.</li></ol>',NULL,64,NULL,1,'2025-09-26 15:30:01','2025-10-04 08:53:57'),(355,'Kualitas Terbaik & Terakreditasi','kualitas-terbaik-terakreditasi','1758881028.png','<p>Terakreditasi <strong>\"Baik Sekali\"</strong> dari BAN-PT adalah jaminan kualitas pendidikan kami. Kami berkomitmen mencetak lulusan kompeten yang siap bersaing di panggung global.</p>',NULL,68,NULL,1,'2025-09-26 17:03:48','2025-10-04 11:32:48'),(356,'Kurikulum Modern & Praktik Nyata','kurikulum-modern-praktik-nyata','1758881087.png','<p>Kurikulum MBKM kami fokus pada praktik langsung di lab modern dan magang industri, membangun portofolio unggul sejak di bangku kuliah.</p>',NULL,70,NULL,1,'2025-09-26 17:04:47','2025-10-04 11:33:09'),(357,'Lulusan Cepat Kerja & Relevan','lulusan-cepat-kerja-relevan','1758881156.png','<p>Masa tunggu kerja super singkat: rata-rata <strong>hanya 3,5 bulan!</strong> Ini adalah bukti nyata bahwa kurikulum kami sangat relevan dengan kebutuhan industri dan mencetak lulusan yang <i>skillful</i>.</p>',NULL,70,NULL,1,'2025-09-26 17:05:56','2025-10-04 11:33:41'),(358,'Peluang Internasional & Jaringan Global','peluang-internasional-jaringan-global','1758881197.png','<p>Melalui program&nbsp;<i>student exchange</i> dan riset bersama universitas di Jepang, kami membuka gerbang karier dan wawasan global untuk semua mahasiswa berprestasi.</p>',NULL,70,NULL,1,'2025-09-26 17:06:37','2025-10-04 11:34:08'),(359,'Dosen Sebagai Mentor & Komunitas Suportif','dosen-sebagai-mentor-komunitas-suportif','1758881259.png','<p>Di Universitas BTH, dosen menjadi mentor yang siap membimbing akademik dan pengembangan dirimu. Rasakan suasana belajar suportif yang terasa seperti rumah kedua.</p>',NULL,70,NULL,1,'2025-09-26 17:07:39','2025-10-04 11:35:13'),(360,'Lokasi Strategis di Jantung Kota','lokasi-strategis-di-jantung-kota','1758881387.png','<p>Kampus kami mudah diakses dari stasiun, terminal, dan bandara. Dikelilingi pusat bisnis, lokasi kami membuka ribuan peluang magang dan kerja paruh waktu sejak awal kuliah.</p>',NULL,70,NULL,1,'2025-09-26 17:09:47','2025-10-06 08:51:30'),(361,'Visi yang Jelas dan Spesifik','visi-yang-jelas-dan-spesifik','1758954049.jpg','<p>Prodi memiliki visi melahirkan lulusan unggul dan inovatif dalam keperawatan kardiovaskuler serta berdaya saing nasional. Fokus ini memberikan arah yang jelas dan nilai tambah, karena kardiovaskuler merupakan salah satu bidang prioritas kesehatan di Indonesia&nbsp;</p>',NULL,57,NULL,1,'2025-09-27 13:20:49','2025-10-04 09:03:39'),(362,'Lulusan Teknologi Pangan akan Selalu Dibutuhkan','lulusan-teknologi-pangan-akan-selalu-dibutuhkan','1759483720.jpg','<p>&nbsp;Semua orang butuh makanan, dan selama manusia hidup maka teknologi pangan akan terus dibutuhkan, jadi ilmu pangan selalu kepake dan prospeknya luas banget.</p>',NULL,62,0,1,'2025-10-03 16:28:40','2025-10-03 16:28:40'),(363,'Fokus pada Bidang Gizi dan Kesehatan','fokus-pada-bidang-gizi-dan-kesehatan','1759483824.jpg','<p>Buat kamu yang peduli sama gaya hidup sehat dan masa depan pangan, prodi ini ngasih ilmu keren seputar gizi, pangan, dan kesehatan. Bisa banget jadi bekal buat karier atau bisnis di bidang ini.</p>',NULL,62,0,1,'2025-10-03 16:30:24','2025-10-03 16:30:24'),(364,'Ilmu + Praktek di Lab','ilmu-praktek-di-lab','1759483950.jpg','<p>&nbsp;Nggak cuma teori, kamu juga langsung eksperimen pake alat modern buat cek kualitas dan bikin produk baru dengan fasilitas laboratorium yang lengkap dan mutakhir. Kamu juga bisa praktek bikin berbagai jenis produk makanan dari mulai snack sehat, minuman hits, sampai makanan halal kekinian, kamu bisa jadi inovatornya.</p>',NULL,62,0,1,'2025-10-03 16:32:30','2025-10-03 16:32:30'),(365,'Peluang Kerja Luas','peluang-kerja-luas','1759484006.jpg','<p>Bisa masuk industri makanan besar, lembaga riset, pemerintah, atau malah bikin usaha sendiri.</p>',NULL,62,0,1,'2025-10-03 16:33:26','2025-10-03 16:33:26'),(366,'Dilatih Jadi Wirausaha','dilatih-jadi-wirausaha','1759484047.jpg','<p>Jadi bukan cuma siap kerja, tapi juga siap bikin bisnis makanan yang bisa go nasional bahkan global.</p>',NULL,62,0,1,'2025-10-03 16:34:07','2025-10-03 16:34:07'),(367,'Banyak Koneksi','banyak-koneksi','1759484090.jpg','<p>Ada kerja sama dengan industri, kampus lain, bahkan internasional. Jadi kesempatan magang &amp; belajar makin terbuka lebar.</p>',NULL,62,NULL,1,'2025-10-03 16:34:50','2025-10-03 16:37:11'),(368,'Lulusan Unggul & Berdaya Saing Nasional','lulusan-unggul-berdaya-saing-nasional','1759484565.jpg','<p>Kurikulum dirancang agar mahasiswa tidak hanya kompeten secara akademik, tetapi juga siap bersaing di tingkat nasional dengan sertifikasi dan pengalaman praktik yang relevan.<br><br>&nbsp;</p>',NULL,70,0,0,'2025-10-03 16:42:45','2025-10-03 16:42:45'),(369,'Lulusan Unggul & Berdaya Saing Nasional','lulusan-unggul-berdaya-saing-nasional','1759484691.jpg','<p>Kurikulum dirancang agar mahasiswa tidak hanya kompeten secara akademik, tetapi juga siap bersaing di tingkat nasional dengan sertifikasi dan pengalaman praktik yang relevan.<br><br>&nbsp;</p>',NULL,58,0,0,'2025-10-03 16:44:51','2025-10-03 16:44:51'),(370,'Belajar di \"Jantungnya\" Ekosistem Kesehatan','belajar-di-jantungnya-ekosistem-kesehatan','1759485636.jpg','<p>Mahasiswa mempelajari teori sekaligus praktik langsung di rumah sakit sehingga kompetensi yang diperoleh lebih aplikatif.</p>',NULL,66,0,1,'2025-10-03 17:00:37','2025-10-03 17:00:37'),(371,'Kurikulum Modern yang Siap Hadapi Tantangan Digital','kurikulum-modern-yang-siap-hadapi-tantangan-digital','1759485703.jpg','<p>Materi dirancang mengikuti perkembangan teknologi informasi kesehatan untuk menghadapi era digitalisasi layanan.</p>',NULL,66,0,1,'2025-10-03 17:01:43','2025-10-03 17:01:43'),(372,'Jaringan Kerja Sama Luas untuk Magang dan Karier','jaringan-kerja-sama-luas-untuk-magang-dan-karier','1759485789.jpg','<p>Didukung mitra rumah sakit, klinik, dan instansi kesehatan yang membuka akses magang dan peluang kerja.</p>',NULL,66,0,1,'2025-10-03 17:03:09','2025-10-03 17:03:09'),(373,'Dosen adalah Praktisi, Belajar Langsung dari Ahlinya','dosen-adalah-praktisi-belajar-langsung-dari-ahlinya','1759485855.jpg','<p>Proses belajar difasilitasi oleh dosen sekaligus praktisi, memastikan keterkaitan antara teori dan realita industri.</p>',NULL,66,0,1,'2025-10-03 17:04:15','2025-10-03 17:04:15'),(374,'Prospek Karier Sangat Cerah dan Spesifik','prospek-karier-sangat-cerah-dan-spesifik','1759485914.jpg','<p>Lulusan siap berkarier di bidang manajemen rumah sakit, konsultan kesehatan, dan pengembangan sistem informasi kesehatan.</p><p><br>&nbsp;</p>',NULL,66,0,1,'2025-10-03 17:05:14','2025-10-03 17:05:14'),(375,'Keunggulan Lokasi Strategis dengan Biaya Hidup Terjangkau','keunggulan-lokasi-strategis-dengan-biaya-hidup-terjangkau','1759485974.jpg','<p>Kampus berada di lokasi strategis dengan biaya hidup yang relatif terjangkau bagi mahasiswa.</p>',NULL,66,0,1,'2025-10-03 17:06:14','2025-10-03 17:06:14'),(376,'Kurikulum Mendukung Berwirausaha di Tingkat Lokal, Nasional, dan Global','kurikulum-mendukung-berwirausaha-di-tingkat-lokal-nasional-dan-global','1759486053.jpg','<p>Mahasiswa dibekali kurikulum aplikatif yang relevan dengan perkembangan usaha di berbagai skala.</p>',NULL,69,0,1,'2025-10-03 17:07:33','2025-10-03 17:07:33'),(377,'Dosen Berpengalaman di Industri Lokal, Nasional, dan Global','dosen-berpengalaman-di-industri-lokal-nasional-dan-global','1759486185.jpg','<p>Pengajaran diberikan oleh tenaga pendidik yang memiliki rekam jejak praktis di dunia usaha.</p>',NULL,69,0,1,'2025-10-03 17:09:45','2025-10-03 17:09:45'),(378,'Didukung oleh Praktisi Kewirausahaan','didukung-oleh-praktisi-kewirausahaan','1759486230.jpg','<p>Mahasiswa mendapatkan bimbingan langsung dari praktisi untuk memperkuat keterampilan wirausaha.</p>',NULL,69,0,1,'2025-10-03 17:10:30','2025-10-03 17:10:30'),(379,'Memiliki Jejaring yang Luas di Tingkat Lokal, Nasional, dan Global','memiliki-jejaring-yang-luas-di-tingkat-lokal-nasional-dan-global','1759486260.jpg','<p>Kolaborasi dengan berbagai mitra usaha membuka akses kerja sama dan peluang bisnis.</p>',NULL,69,0,1,'2025-10-03 17:11:00','2025-10-03 17:11:00'),(380,'Akses Magang di Perusahaan Lokal dan Nasional','akses-magang-di-perusahaan-lokal-dan-nasional','1759486298.jpg','<p>Program magang memberi pengalaman nyata dalam mengelola bisnis secara profesional.</p>',NULL,69,0,1,'2025-10-03 17:11:38','2025-10-03 17:11:38'),(381,'Stimulus Permodalan Usaha bagi Mahasiswa','stimulus-permodalan-usaha-bagi-mahasiswa','1759486334.jpg','<p>Dukungan permodalan diberikan sebagai bentuk fasilitasi pengembangan usaha mahasiswa.</p>',NULL,69,0,1,'2025-10-03 17:12:14','2025-10-03 17:12:14'),(382,'Dosen Profesional & Berpengalaman','dosen-profesional-berpengalaman','1759541717.jpg','<p>Didukung tenaga pendidik dengan kualifikasi S2–S3, berpengalaman dalam penelitian, publikasi, dan praktik klinis keperawatan.<br><br>&nbsp;</p>',NULL,58,NULL,1,'2025-10-04 08:35:17','2025-10-04 08:36:44'),(383,'Pendidikan Berbasis Mutu & Etika','pendidikan-berbasis-mutu-etika','1759541927.jpg','<p>Proses pembelajaran mengintegrasikan standar mutu pendidikan tinggi dengan nilai etika profesi, sehingga membentuk perawat yang kompeten sekaligus humanis.</p>',NULL,58,0,1,'2025-10-04 08:38:47','2025-10-04 08:38:47'),(384,'Tridharma yang Kuat','tridharma-yang-kuat','1759542011.jpg','<p>Mahasiswa dibekali pengalaman dalam pendidikan, penelitian berbasis evidence, dan pengabdian masyarakat, khususnya terkait isu kesehatan kardiovaskuler.<br><br>&nbsp;</p>',NULL,58,0,1,'2025-10-04 08:40:11','2025-10-04 08:40:11'),(385,'Jaringan & Kerjasama Luas','jaringan-kerjasama-luas','1759542102.jpg','<p>PSPPN UBTH menjalin kemitraan dengan rumah sakit, institusi pendidikan, dan stakeholder baik di dalam maupun luar negeri, membuka peluang magang, penelitian, hingga karier.</p>',NULL,58,0,1,'2025-10-04 08:41:42','2025-10-04 08:41:42'),(386,'Fokus pada Digitalpreneur','fokus-pada-digitalpreneur','1759542450.jpg','<p>Tidak hanya menyiapkan mahasiswa untuk bekerja, tetapi juga membekali mereka menjadi pengusaha digital yang inovatif, mandiri, dan berdaya saing global.<br><br>&nbsp;</p>',NULL,68,0,1,'2025-10-04 08:47:30','2025-10-04 08:47:30'),(387,'Kolaborasi dengan Industri','kolaborasi-dengan-industri','1759542519.jpg','<p>Program studi memiliki jaringan kerjasama dengan dunia usaha, startup, dan industri kreatif, sehingga mahasiswa mendapat peluang magang, proyek nyata, hingga rekrutmen kerja.<br><br>&nbsp;</p>',NULL,68,0,1,'2025-10-04 08:48:39','2025-10-04 08:48:39'),(388,'Fasilitas Inkubasi Bisnis','fasilitas-inkubasi-bisnis','1759542596.jpg','<p>Mahasiswa difasilitasi untuk mengembangkan ide bisnis melalui pusat inkubasi yang berkolaborasi dengan wirausaha lokal, sehingga bisa langsung berlatih menciptakan bisnis nyata.<br><br>&nbsp;</p>',NULL,68,0,1,'2025-10-04 08:49:56','2025-10-04 08:49:56'),(389,'Dosen Praktisi & Akademisi','dosen-praktisi-akademisi','1759542659.jpg','<p>Perkuliahan diampu oleh dosen yang tidak hanya berpengalaman akademis, tetapi juga praktisi bisnis digital, sehingga materi kuliah selalu aplikatif dan sesuai tren.<br><br>&nbsp;</p>',NULL,68,0,1,'2025-10-04 08:50:59','2025-10-04 08:50:59'),(390,'Peluang Karir Luas','peluang-karir-luas','1759542717.jpg','<p>Lulusan dapat berkarir sebagai digital marketer, business analyst, startup founder, content strategist, hingga konsultan bisnis digital yang sangat dibutuhkan di era transformasi digital 4.0.<br><br>&nbsp;</p>',NULL,68,0,1,'2025-10-04 08:51:57','2025-10-04 08:51:57'),(392,'Fokus pada Kewirausahaan Farmasi','fokus-pada-kewirausahaan-farmasi','1759542917.jpg','<ol><li>Mahasiswa tidak hanya dibekali ilmu kefarmasian, tetapi juga keterampilan menciptakan produk dan usaha farmasi yang mandiri serta kompetitif.</li></ol>',NULL,64,0,1,'2025-10-04 08:55:17','2025-10-04 08:55:17'),(393,'Penelitian Berbasis Inovasi','penelitian-berbasis-inovasi','1759542987.jpg','<ol><li>Prodi mendorong mahasiswa untuk aktif dalam penelitian, khususnya yang berhubungan dengan kewirausahaan produk farmasi dan pengembangan kesehatan.</li></ol>',NULL,64,0,1,'2025-10-04 08:56:27','2025-10-04 08:56:27'),(394,'Pengabdian Masyarakat','pengabdian-masyarakat','1759543112.jpg','<ol><li>Melalui program berbasis hasil penelitian, mahasiswa berkontribusi dalam solusi kesehatan, khususnya terkait kebutuhan farmasi masyarakat.</li></ol><p>&nbsp;</p>',NULL,64,0,1,'2025-10-04 08:58:32','2025-10-04 08:58:32'),(395,'Akreditasi Baik Sekali','akreditasi-baik-sekali','1759543170.jpg','<ol><li>Prodi S1 Farmasi Universitas BTH telah terakreditasi dengan peringkat Baik Sekali, menjadi bukti kualitas dan mutu penyelenggaraan pendidikan.</li></ol>',NULL,64,0,1,'2025-10-04 08:59:30','2025-10-04 08:59:30'),(396,'Peluang Karier Luas','peluang-karier-luas','1759543234.jpg','<ol><li>Lulusan memiliki kompetensi sebagai Communicator, Manager, Decision Maker, Leader, Care Giver, Teacher/Educator/Drug Informer, Life Long Learner, dan Entrepreneur yang siap bersaing di tingkat nasional maupun global.</li></ol>',NULL,64,0,1,'2025-10-04 09:00:34','2025-10-04 09:00:34'),(397,'Dosen Kompeten dan Profesional','dosen-kompeten-dan-profesional','1759543487.jpg','<p>Seluruh dosen berasal dari latar belakang keilmuan keperawatan dan bidang terkait, sehingga mahasiswa dibimbing oleh tenaga pendidik yang ahli, berpengalaman, dan relevan dengan kebutuhan dunia kesehatan.<br>&nbsp;</p>',NULL,57,0,1,'2025-10-04 09:04:47','2025-10-04 09:04:47'),(398,'Fasilitas Laboratorium dan Alat Praktik Lengkap','fasilitas-laboratorium-dan-alat-praktik-lengkap','1759543543.jpg','<p>Laboratorium modern dengan alat praktik sesuai standar pendidikan keperawatan memungkinkan mahasiswa menguasai keterampilan klinik sejak dini, sehingga lebih siap menghadapi tahap Profesi Ners maupun dunia kerja.</p>',NULL,57,0,1,'2025-10-04 09:05:43','2025-10-04 09:05:43'),(399,'Lahan Praktik yang Luas dan Terjamin','lahan-praktik-yang-luas-dan-terjamin','1759543600.jpg','<p>Tersedia lahan praktik di rumah sakit, puskesmas, dan komunitas yang mendukung tercapainya capaian pembelajaran. Dengan demikian, mahasiswa memperoleh pengalaman nyata dalam menghadapi pasien dan berbagai kasus kesehatan.<br>&nbsp;</p>',NULL,57,0,1,'2025-10-04 09:06:40','2025-10-04 09:06:40'),(400,'Tridharma Perguruan Tinggi yang Terintegrasi','tridharma-perguruan-tinggi-yang-terintegrasi','1759543651.jpg','<p>Prodi aktif menyelenggarakan pendidikan, penelitian, dan pengabdian masyarakat berbasis keperawatan kardiovaskuler. Mahasiswa tidak hanya belajar teori, tetapi juga dilibatkan dalam riset dan program pemberdayaan masyarakat&nbsp;</p>',NULL,57,0,1,'2025-10-04 09:07:31','2025-10-04 09:07:31'),(401,'Jaringan Kemitraan Nasional dan Internasional','jaringan-kemitraan-nasional-dan-internasional','1759543702.jpg','<p>Program studi menjalin kerja sama dengan berbagai pemangku kepentingan dalam dan luar negeri, sehingga membuka peluang mahasiswa untuk memperoleh pengalaman lebih luas, baik dalam praktik, penelitian, maupun pengembangan karier&nbsp;<br>&nbsp;</p>',NULL,57,0,1,'2025-10-04 09:08:22','2025-10-04 09:08:22'),(402,'Peran Vital dalam Medis','peran-vital-dalam-medis','1759545111.jpg','<p>Tenaga kesehatan memiliki peran vital dalam menjaga, memulihkan, dan meningkatkan kualitas hidup manusia melalui penyembuhan, pencegahan penyakit, edukasi, serta dukungan emosional. Kolaborasi antarprofesi menjadi fondasi terciptanya pelayanan medis yang bermutu, beretika, dan berorientasi pada keselamatan pasien.</p>',NULL,63,0,1,'2025-10-04 09:31:51','2025-10-04 09:31:51'),(403,'Kesehatan Kebutuhan Abadi','kesehatan-kebutuhan-abadi','1759545302.jpg','<p>Kesehatan adalah kebutuhan abadi yang tidak pernah lekang oleh waktu, sebab tanpa kesehatan segala pencapaian dan impian akan sulit terwujud. Sehat bukan hanya bebas dari penyakit, tetapi juga keseimbangan fisik, mental, dan sosial yang memungkinkan manusia menjalani kehidupan dengan penuh makna.</p>',NULL,63,0,0,'2025-10-04 09:35:02','2025-10-04 09:35:02'),(404,'Banyak Pilihan Tempat Kerja','banyak-pilihan-tempat-kerja','1759545399.jpg','<p>Di era modern, peluang kerja semakin beragam dan fleksibel, tidak hanya terbatas pada kantor konvensional, tetapi juga bisa dilakukan di coworking space, kafe, hingga dari rumah dengan sistem remote. Setiap tempat kerja memiliki suasana dan keunggulan masing-masing, sehingga individu dapat memilih lingkungan yang sesuai agar bekerja lebih dinamis, nyaman, dan produktif.</p>',NULL,63,0,1,'2025-10-04 09:36:39','2025-10-04 09:36:39'),(405,'Gaji dan Jenjang Karier Kompetitif','gaji-dan-jenjang-karier-kompetitif','1759545539.jpg','<p>Program studi ini menawarkan peluang kerja dengan gaji yang kompetitif sesuai dengan keahlian dan kualifikasi lulusan. Selain itu, tersedia jenjang karier yang jelas dan beragam sehingga setiap individu dapat terus berkembang dan meningkatkan profesionalisme di bidangnya.</p>',NULL,63,0,0,'2025-10-04 09:38:59','2025-10-04 09:38:59'),(406,'Memiliki kesempatan untuk membuka laboratorium diagnostik sendiri','memiliki-kesempatan-untuk-membuka-laboratorium-diagnostik-sendiri','1759545651.jpg','<p>Menjadi tenaga kesehatan tidak hanya membuka peluang bekerja di berbagai fasilitas medis, tetapi juga memberi kesempatan untuk mandiri dengan membuka laboratorium diagnostik sendiri. Dengan pengetahuan, keterampilan, serta sertifikasi yang dimiliki, tenaga profesional dapat menghadirkan layanan pemeriksaan kesehatan yang akurat sekaligus berkontribusi pada kualitas layanan masyarakat serta membuka peluang wirausaha di bidang medis yang menjanjikan.</p>',NULL,63,0,0,'2025-10-04 09:40:51','2025-10-04 09:40:51'),(409,'Visi yang Relevan dengan Masa Depan','visi-yang-relevan-dengan-masa-depan','1759546186.jpg','<p>Program studi ini berfokus pada inovasi dan transformasi digital di sektor kesehatan dan ekonomi kreatif – dua bidang yang berkembang pesat dan sangat dibutuhkan di era digital.<br>&nbsp;</p>',NULL,65,0,0,'2025-10-04 09:49:46','2025-10-04 09:49:46'),(410,'Kurikulum Berbasis Kebutuhan Industri','kurikulum-berbasis-kebutuhan-industri','1759546270.jpg','<p>Materi pembelajaran dirancang selaras dengan perkembangan teknologi, analitik data, kecerdasan buatan, serta tren ekonomi kreatif sehingga lulusan siap menghadapi tantangan dunia kerja maupun wirausaha digital</p>',NULL,65,NULL,1,'2025-10-04 09:51:10','2025-10-04 13:51:41'),(411,'Dosen Kompeten dan Berpengalaman','dosen-kompeten-dan-berpengalaman','1759546394.jpg','<p>Didukung oleh tenaga pengajar akademisi sekaligus praktisi di bidang sistem informasi, teknologi kesehatan, dan bisnis digital kreatif, sehingga mahasiswa mendapatkan teori sekaligus pengalaman praktis.<br>&nbsp;</p>',NULL,65,0,0,'2025-10-04 09:53:14','2025-10-04 09:53:14'),(412,'Kolaborasi dengan Dunia Industri dan Pemerintah','kolaborasi-dengan-dunia-industri-dan-pemerintah','1759546457.jpg','<p>Universitas BTH menjalin kemitraan dengan sektor kesehatan, startup digital, dan komunitas ekonomi kreatif di Priangan Timur, membuka peluang magang, penelitian, hingga penyaluran kerja.<br>&nbsp;</p>',NULL,65,0,1,'2025-10-04 09:54:17','2025-10-04 09:54:17'),(413,'Pengembangan Soft Skills dan Entrepreneurial Mindset','pengembangan-soft-skills-dan-entrepreneurial-mindset','1759546507.jpg','<p>Selain kompetensi teknis, mahasiswa juga dibekali keterampilan komunikasi, manajemen proyek, kepemimpinan, serta jiwa kewirausahaan digital untuk menjadi inovator dan pencipta lapangan kerja.<br>&nbsp;</p>',NULL,65,0,0,'2025-10-04 09:55:07','2025-10-04 09:55:07'),(414,'Laboratorium & Ekosistem Digital yang Mendukung','laboratorium-ekosistem-digital-yang-mendukung','1759546561.jpg','<p>Fasilitas laboratorium komputer, akses ke platform digital, serta lingkungan akademik kreatif mendorong mahasiswa mengembangkan ide inovatif yang berdampak nyata bagi masyarakat.</p>',NULL,65,0,0,'2025-10-04 09:56:01','2025-10-04 09:56:01'),(415,'Biaya terjangkau dan fleksibel,','biaya-terjangkau-dan-fleksibel','1759547365.jpg','<p>Dengan biaya yang terjangkau serta sistem pembayaran yang fleksibel, layanan ini dirancang agar dapat diakses oleh semua kalangan tanpa mengurangi kualitas. Fleksibilitas yang ditawarkan memungkinkan setiap orang menyesuaikan kebutuhan dan kemampuan, sehingga lebih praktis dan tidak memberatkan</p>',NULL,67,0,0,'2025-10-04 10:09:25','2025-10-04 10:09:25'),(416,'Kurikulum Kewirausahaan (Entrepreneurship) yang Inovatif','kurikulum-kewirausahaan-entrepreneurship-yang-inovatif','1759547464.jpg','<p>Mahasiswa dibekali dengan kurikulum yang menekankan pengembangan jiwa wirausaha di bidang kefarmasian.</p>',NULL,70,0,1,'2025-10-04 10:11:04','2025-10-04 10:11:04'),(417,'Kampus bersih, nyaman, dan religius.','kampus-bersih-nyaman-dan-religius','1759547547.jpg','<p>Kampus yang bersih akan menciptakan suasana nyaman bagi seluruh civitas akademika.Selain itu, lingkungan kampus yang religius mampu membentuk karakter mahasiswa yang berakhlak mulia.</p>',NULL,67,0,0,'2025-10-04 10:12:27','2025-10-04 10:12:27'),(418,'Lulusan tersebar dalam dan luar negeri sejak Tahun 1993','lulusan-tersebar-dalam-dan-luar-negeri-sejak-tahun-1993','1759547624.jpg','<p>Sejak tahun 1993, lulusan telah tersebar di berbagai wilayah dalam negeri. Tidak hanya itu, lulusan juga banyak yang berkiprah di luar negeri.</p>',NULL,67,0,0,'2025-10-04 10:13:44','2025-10-04 10:13:44'),(419,'Mayoritas pengguna lulusan puas dengan kualitas lulusan Prodi D3 Keperawatan,','mayoritas-pengguna-lulusan-puas-dengan-kualitas-lulusan-prodi-d3-keperawatan','1759547759.jpg','<p>Mayoritas pengguna lulusan menyatakan puas terhadap kualitas lulusan Prodi D3 Keperawatan. Hal ini menunjukkan bahwa Prodi D3 Keperawatan mampu menghasilkan lulusan yang sesuai dengan kebutuhan dunia kerja.</p>',NULL,67,0,0,'2025-10-04 10:15:59','2025-10-04 10:15:59'),(420,'Fokus pada Inovasi Produk dan Layanan Farmasi','fokus-pada-inovasi-produk-dan-layanan-farmasi','1759547838.jpg','<p>Pembelajaran diarahkan pada penciptaan produk dan layanan farmasi yang relevan dengan kebutuhan industri kesehatan.</p>',NULL,70,0,1,'2025-10-04 10:17:18','2025-10-04 10:17:18'),(421,'Dosen profesional lulusan dalam dan luar negeri,','dosen-profesional-lulusan-dalam-dan-luar-negeri','1759547872.jpg','<p>Dosen profesional lulusan dalam dan luar negeri siap memberikan pengalaman belajar terbaik bagi mahasiswa. Program studi Keperawatan didukung oleh tenaga pendidik yang kompeten dan berpengalaman secara global.</p>',NULL,67,0,0,'2025-10-04 10:17:52','2025-10-04 10:17:52'),(422,'Dosen dan Mentor dari Praktisi & Entrepreneur','dosen-dan-mentor-dari-praktisi-entrepreneur','1759547875.jpg','<p>Proses pendidikan didukung oleh tenaga ahli yang aktif di dunia farmasi dan kewirausahaan.</p>',NULL,70,0,1,'2025-10-04 10:17:55','2025-10-04 10:17:55'),(423,'Fasilitas Pendukung yang Modern dan Lengkap','fasilitas-pendukung-yang-modern-dan-lengkap','1759547913.jpg','<p>Mahasiswa memperoleh pengalaman belajar dengan dukungan laboratorium dan sarana pembelajaran mutakhir.</p>',NULL,70,0,1,'2025-10-04 10:18:33','2025-10-04 10:18:33'),(424,'Penguasaan Literasi Data & AI dalam Kefarmasian','penguasaan-literasi-data-ai-dalam-kefarmasian','1759547951.jpg','<p>Lulusan dipersiapkan untuk menguasai teknologi data dan kecerdasan buatan sebagai bagian dari perkembangan farmasi modern.</p>',NULL,70,0,1,'2025-10-04 10:19:11','2025-10-04 10:19:11'),(425,'Jaringan Kemitraan yang Luas dengan Industri dan Pelaku Usaha','jaringan-kemitraan-yang-luas-dengan-industri-dan-pelaku-usaha','1759547998.jpg','<p>Kerja sama strategis dengan industri dan berbagai mitra usaha memperluas peluang pengembangan karier mahasiswa.</p>',NULL,70,0,1,'2025-10-04 10:19:58','2025-10-04 10:19:58'),(426,'Berada di dekat pusat Kota Tasikmalaya','berada-di-dekat-pusat-kota-tasikmalaya','1759548449.jpg','<p>Berada di dekat pusat Kota Tasikmalaya memberikan akses mudah ke berbagai fasilitas umum.<br>Lokasi ini juga strategis untuk menunjang aktivitas sehari-hari maupun bisnis.</p>',NULL,67,0,0,'2025-10-04 10:27:29','2025-10-04 10:27:29'),(427,'Prospek Kerja yang Luas dan Stabil','prospek-kerja-yang-luas-dan-stabil','1759548670.jpg','<p>Prospek kerja di bidang ini sangat luas karena dibutuhkan di berbagai sektor. Selain itu, peluang kerjanya juga stabil sehingga memberikan jaminan masa depan yang lebih terarah.</p>',NULL,61,0,0,'2025-10-04 10:31:10','2025-10-04 10:31:10'),(428,'Sebanyak 98% lulusan cepat kerja, maksimal 3 bulan setelah lulus  (Merujuk Hasil Tracer Studi Lulusan Tahun 2025)','sebanyak-98-lulusan-cepat-kerja-maksimal-3-bulan-setelah-lulus-merujuk-hasil-tracer-studi-lulusan-tahun-2025','1759548730.jpg','<p>Sebanyak 98% lulusan berhasil mendapatkan pekerjaan dengan cepat. Mayoritas terserap ke dunia kerja maksimal dalam waktu tiga bulan setelah lulus, sesuai hasil tracer studi lulusan tahun 2025.</p>',NULL,61,0,0,'2025-10-04 10:32:10','2025-10-04 10:32:10'),(429,'Menjadi Tenaga Kesehatan Profesional','menjadi-tenaga-kesehatan-profesional','1759548807.jpg','<p>Menjadi tenaga kesehatan profesional membutuhkan dedikasi, ilmu, dan keterampilan yang terus dikembangkan. Seorang tenaga kesehatan profesional dituntut untuk bekerja dengan penuh tanggung jawab demi keselamatan dan kesejahteraan pasien.</p>',NULL,61,0,0,'2025-10-04 10:33:27','2025-10-04 10:33:27'),(430,'Peluang Berwirausaha besar (usaha optik atau klinik mata sendiri)','peluang-berwirausaha-besar-usaha-optik-atau-klinik-mata-sendiri','1759548881.jpg','<p>Peluang berwirausaha di bidang kesehatan mata sangat besar, baik melalui usaha optik maupun klinik mata sendiri.Dengan meningkatnya kebutuhan masyarakat akan layanan kesehatan mata, usaha ini berpotensi memberikan keuntungan yang menjanjikan.</p>',NULL,61,0,0,'2025-10-04 10:34:41','2025-10-04 10:34:41'),(431,'penghasilan rata-rata  lulusan 3, 3 juta/bulan  (berdasarkan hasil tracer studi lulusan tahun 2025','penghasilan-rata-rata-lulusan-3-3-jutabulan-berdasarkan-hasil-tracer-studi-lulusan-tahun-2025','1759548953.jpg','<p>Berdasarkan hasil tracer studi lulusan tahun 2025, diketahui bahwa penghasilan rata-rata lulusan mencapai Rp3,3 juta per bulan. Temuan ini memberikan gambaran mengenai daya saing dan kemandirian ekonomi para lulusan di dunia kerja.</p>',NULL,61,0,0,'2025-10-04 10:35:53','2025-10-04 10:35:53'),(432,'penghasilan rata-rata  lulusan 3, 3 juta/bulan  (berdasarkan hasil tracer studi lulusan tahun 2025','penghasilan-rata-rata-lulusan-3-3-jutabulan-berdasarkan-hasil-tracer-studi-lulusan-tahun-2025','1759548956.jpg','<p>Berdasarkan hasil tracer studi lulusan tahun 2025, diketahui bahwa penghasilan rata-rata lulusan mencapai Rp3,3 juta per bulan. Temuan ini memberikan gambaran mengenai daya saing dan kemandirian ekonomi para lulusan di dunia kerja.</p>',NULL,61,0,0,'2025-10-04 10:35:56','2025-10-04 10:35:56'),(433,'Jago Medisnya Jago Bisnisnya; terdapat kelas ikatan dinas dengan optikal melawai (multinasional)','jago-medisnya-jago-bisnisnya-terdapat-kelas-ikatan-dinas-dengan-optikal-melawai-multinasional','1759549022.jpg','<p><i>Jago medisnya, jago juga bisnisnya. Tersedia kelas ikatan dinas bersama Optik Melawai, perusahaan multinasional ternama.</i></p>',NULL,61,0,0,'2025-10-04 10:37:02','2025-10-04 10:37:02'),(434,'Spesialisasi Prospek Tinggi','spesialisasi-prospek-tinggi','1759551641.webp','<p>Program studi kami fokus pada spesialisasi yang dibutuhkan industri, memastikan lulusan memiliki keunggulan kompetitif nyata.</p>',NULL,70,1,0,'2025-10-04 11:20:41','2025-10-04 11:20:41'),(435,'Pembelajaran Proyek & AI','pembelajaran-proyek-ai','1759551681.webp','<p>Kurikulum kami menekankan kolaborasi dan proyek nyata dengan dukungan AI untuk membangun portofolio relevan.</p>',NULL,70,1,0,'2025-10-04 11:21:21','2025-10-04 11:21:21'),(437,'Jaringan Kemitraan Global','jaringan-kemitraan-global','1759551819.webp','<p>Kemitraan strategis kami membuka peluang luas untuk pertukaran pelajar, magang, dan rekrutmen pasca-kelulusan.</p>',NULL,70,1,0,'2025-10-04 11:23:39','2025-10-04 11:23:39'),(438,'Mentor Praktisi Industri','mentor-praktisi-industri','1759551882.webp','<p>Anda akan dibimbing secara personal oleh jajaran dosen akademisi dan praktisi berpengalaman dari industri.</p>',NULL,70,1,0,'2025-10-04 11:24:42','2025-10-04 11:24:42'),(439,'Kualitas Terakreditasi Penuh','kualitas-terakreditasi-penuh','1759552254.webp','<p>Kami memberikan jaminan kualitas pendidikan yang telah diakui secara resmi oleh lembaga akreditasi nasional.</p>',NULL,70,1,0,'2025-10-04 11:30:54','2025-10-04 11:30:54'),(440,'Investasi Pendidikan Rasional','investasi-pendidikan-rasional','1759552309.webp','<p>Kami menawarkan struktur biaya yang transparan dan rasional, didukung oleh berbagai pilihan beasiswa unggulan.</p>',NULL,70,1,0,'2025-10-04 11:31:49','2025-10-04 11:31:49'),(441,'Jaringan Alumni Sukses','jaringan-alumni-sukses','1759552333.webp','<p>Menjadi bagian dari ribuan alumni sukses yang telah berkarya di tingkat nasional maupun internasional.</p>',NULL,70,1,0,'2025-10-04 11:32:13','2025-10-04 11:32:13'),(442,'Fasilitas Riset & Inovasi','fasilitas-riset-inovasi','1759715740.png','<p>Fasilitas modern kami, dari lab hingga inkubator bisnis, dirancang untuk mendukung proses inovasi Anda.</p>',NULL,70,1,0,'2025-10-06 08:55:40','2025-10-06 08:55:40'),(443,'Lokasi Kampus Strategis','lokasi-kampus-strategis','1759715829.png','<p>Berada di jantung kota Tasikmalaya dengan akses mudah ke berbagai fasilitas transportasi publik utama.</p>',NULL,70,1,0,'2025-10-06 08:57:09','2025-10-06 08:57:09'),(444,'Fokus Unggulan: Pharmapreneurship & Inovasi Bahan Alam','fokus-unggulan-pharmapreneurship-inovasi-bahan-alam','1764147256.jpg','<p>&nbsp;Kami tidak hanya mencetak ilmuwan, tapi&nbsp;<i>pharmapreneur</i>. Kurikulum dirancang untuk mengintegrasikan keahlian riset (khususnya bahan alam lokal) dengan kemampuan bisnis, regulasi, dan pemasaran untuk menciptakan produk farmasi inovatif.</p>',NULL,71,NULL,1,'2025-11-26 15:54:16','2025-11-26 15:55:58'),(445,'Ekosistem Riset Terpadu (S1 - S2)','ekosistem-riset-terpadu-s1-s2','1764147344.jpg','<p>Mahasiswa S2 menjadi motor penggerak riset di lingkungan fakultas. Terdapat integrasi riset yang kuat dengan laboratorium dan kelompok penelitian S1, menciptakan ekosistem akademik yang dinamis dan produktif.</p>',NULL,71,0,1,'2025-11-26 15:55:44','2025-11-26 15:55:44'),(446,'Integrasi Farmasi Digital & Teknologi Kurikulum adaptif terhadap era 4.0.','integrasi-farmasi-digital-teknologi-kurikulum-adaptif-terhadap-era-40','1764147397.jpg','<p>Mahasiswa dibekali keahlian&nbsp;<i>digital health</i>,&nbsp;<i>telepharmacy</i>, dan pemanfaatan&nbsp;<i>big data</i> dalam analisis klinis dan pengembangan obat baru.</p>',NULL,71,0,1,'2025-11-26 15:56:37','2025-11-26 15:56:37'),(447,'Dibimbing Dosen Ahli & Praktisi Industri','dibimbing-dosen-ahli-praktisi-industri','1764147436.jpg','<p>Proses belajar didukung oleh dosen bergelar Doktor (S3) serta praktisi ahli yang menjabat sebagai manajer di industri farmasi, rumah sakit, dan regulator (BPOM), memastikan ilmu yang didapat sangat aplikatif.</p>',NULL,71,0,1,'2025-11-26 15:57:16','2025-11-26 15:57:16'),(448,'Jaringan Kemitraan Strategis','jaringan-kemitraan-strategis','1764147479.jpg','<p>Memiliki jaringan kerjasama yang kuat dengan industri farmasi nasional, rumah sakit rujukan, dan lembaga riset, membuka peluang kolaborasi tesis dan percepatan karir pasca-lulus.</p>',NULL,71,0,1,'2025-11-26 15:57:59','2025-11-26 15:57:59'),(449,'Fokus pada Pengembangan Profesional','fokus-pada-pengembangan-profesional','1764147577.jpg','<p>Lulusan dibekali kemampuan manajerial, analisis kebijakan farmasi, serta etika profesi untuk berperan dalam pendidikan, penelitian, pemerintahan, maupun industri kesehatan.</p>',NULL,71,0,1,'2025-11-26 15:59:37','2025-11-26 15:59:37');
